// Tests for AskApp — the federated entry exposed as "ask/AskApp".
//
// The platform-chrome surface used by AskLayout is stubbed so routing
// tests don't pull in the full Topbar / WebSocket machinery (which would
// crash the jsdom worker). Only the chrome HOOK surface is mocked;
// paraglide/messages stays real so the routes import their translated
// strings normally. Mirrors frontends/spaces-mfe/tests/SpacesApp.test.tsx,
// extended with the #1274 Surveys/Analytics/Settings sidebar routes and the
// bare-/ask → /ask/surveys redirect.
//
// Story #1276 swaps the Surveys placeholder for the real SurveysListRoute
// (its own data/loading/empty states are covered in
// src/routes/__tests__/SurveysListRoute.test.tsx — the default MSW handler
// here returns an empty org, so /ask/surveys settles on the empty hero).
// Story #1277 then replaces the /ask/surveys/new create-placeholder
// destination with the real "Create survey" route (SurveysCreateRoute) —
// its own step/loading/error states are covered in
// src/routes/__tests__/SurveysCreateRoute.test.tsx, so this file only pins
// that the route resolves at the right path. Story #1278 similarly
// replaces the /ask/surveys/:id placeholder with the real, read-only
// SurveyDetailRoute — its own loading/error/generation-status/questions
// states are covered in src/routes/__tests__/SurveyDetailRoute.test.tsx,
// so this file only pins that the route resolves for an arbitrary id
// (using the default MSW handler's "Untitled survey" happy path). Analytics
// / Settings are unaffected and stay on the generic AskPlaceholderRoute.

import { render, screen } from "@testing-library/react";
import { MemoryRouter } from "react-router-dom";
import { vi } from "vitest";

vi.mock("@omnicore-platform/platform-chrome", async () => {
  const actual = await vi.importActual<
    typeof import("@omnicore-platform/platform-chrome")
  >("@omnicore-platform/platform-chrome");
  return {
    ...actual,
    Topbar: () => null,
    useTheme: () => ({ theme: "light", setTheme: () => undefined }),
    useLocale: () => "en-US",
    useWorkspaceList: () => ({
      workspaces: [],
      refetch: async () => undefined,
    }),
  };
});

import AskApp from "../src/AskApp";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

// AskApp's route paths ("/", "/surveys", "/analytics", "/settings") are
// UNPREFIXED — the parent /ask/* match supplies the prefix, exactly like
// clio-mfe / spaces-mfe. In production that prefix comes from shell-mfe's
// nested route; standalone (main.tsx) it comes from BrowserRouter's
// `basename`. Reproduce that here with MemoryRouter's own `basename` so
// sub-path routing (Surveys vs Analytics vs Settings vs the redirect vs the
// landing catch-all) resolves the same way.
function renderAt(path: string) {
  return render(
    <MemoryRouter basename="/ask" initialEntries={[path]}>
      <AskApp />
    </MemoryRouter>,
  );
}

test("renders the Surveys list route at /ask/surveys", () => {
  renderAt("/ask/surveys");
  // The header (title/subtitle/Create CTA) renders synchronously regardless
  // of the survey-list fetch's loading state.
  expect(
    screen.getByRole("heading", { name: m.ask_surveys_list_title() }),
  ).toBeInTheDocument();
});

test("renders the create-survey route at /ask/surveys/new", () => {
  renderAt("/ask/surveys/new");
  expect(
    screen.getByRole("heading", {
      name: m.ask_surveys_create_page_title(),
      level: 1,
    }),
  ).toBeInTheDocument();
  // Step 1's active "Create Manually" chooser card renders as a real
  // <button> whose accessible name is its title plus its body copy — match
  // on the leading title text rather than the full concatenated string.
  expect(
    screen.getByRole("button", {
      name: new RegExp(m.ask_surveys_create_manual_title()),
    }),
  ).toBeInTheDocument();
  // The dynamic /surveys/:id route must not swallow the static /surveys/new
  // route (code review, #1276 fix) — the survey detail route must not
  // render here.
  expect(
    screen.queryByRole("heading", { name: m.ask_survey_editor_questions_title() }),
  ).not.toBeInTheDocument();
});

// Code review (#1276 fix): the SurveyCard link (`/ask/surveys/${id}`) used to
// dead-end on the catch-all landing surface because no /surveys/:id route
// existed. This pins the real destination — SurveyDetailRoute (story #1278
// replaced the placeholder that originally landed here) — resolving for an
// arbitrary survey id, not just a fixed literal. The default MSW handler in
// tests/msw/handlers.ts answers any /ask/surveys/:id with a happy-path
// "Untitled survey" Draft.
test("renders the real survey detail route at /ask/surveys/:id", async () => {
  renderAt("/ask/surveys/some-survey-id");
  // Await the questions-card heading, not the survey <h1>: the header also
  // renders while the questions request is in flight, so the <h1> resolves
  // before the editor body has mounted.
  expect(
    await screen.findByRole("heading", { name: m.ask_survey_editor_questions_title() }),
  ).toBeInTheDocument();
  expect(
    screen.getByRole("heading", { name: "Untitled survey", level: 1 }),
  ).toBeInTheDocument();
});

test("renders the Analytics placeholder at /ask/analytics", () => {
  renderAt("/ask/analytics");
  expect(
    screen.getByRole("heading", { name: m.ask_analytics_heading() }),
  ).toBeInTheDocument();
});

test("renders the Settings placeholder at /ask/settings", () => {
  renderAt("/ask/settings");
  expect(
    screen.getByRole("heading", { name: m.ask_settings_heading() }),
  ).toBeInTheDocument();
});

test("redirects the bare /ask root to the Surveys list route", () => {
  renderAt("/ask");
  expect(
    screen.getByRole("heading", { name: m.ask_surveys_list_title() }),
  ).toBeInTheDocument();
});

test("falls back to the landing surface for an unknown path", () => {
  renderAt("/ask/does-not-exist-yet");
  expect(
    screen.getByRole("heading", { name: m.ask_landing_heading() }),
  ).toBeInTheDocument();
});

test("renders the persistent sidebar with all three nav destinations on every route", () => {
  renderAt("/ask/analytics");
  expect(
    screen.getByRole("link", { name: m.ask_nav_surveys() }),
  ).toBeInTheDocument();
  expect(
    screen.getByRole("link", { name: m.ask_nav_analytics() }),
  ).toBeInTheDocument();
  expect(
    screen.getByRole("link", { name: m.ask_nav_settings() }),
  ).toBeInTheDocument();
});

// The shared "coming soon" badge still renders on the remaining placeholder
// surfaces (AskPlaceholderRoute reuses m.ask_landing_badge() for every
// not-yet-built sub-route, same as the landing catch-all). /ask itself no
// longer exercises this — story #1276 replaced the Surveys placeholder with
// the real list route, which renders no such badge — so this now targets
// Analytics, still a genuine placeholder.
test("renders the coming-soon badge on the remaining placeholder routes", () => {
  renderAt("/ask/analytics");
  expect(screen.getByText(m.ask_landing_badge())).toBeInTheDocument();
});

// Stage 3 "Luminous Depth" — the landing/empty placeholder is the §1.7 BOLD
// moment: the hero panel renders on the brand gradient with white-on-gradient
// type, not a flat surface. AskLandingRoute is reached only via the catch-all
// now that the /ask root redirects to Surveys instead, so these assert
// against the unknown-path catch-all render. Content is still queried
// semantically through m.ask_landing_*().

function renderLanding(): void {
  renderAt("/ask/does-not-exist-yet");
}

test("landing hero panel renders on the brand gradient as a bold panel", () => {
  renderLanding();
  const panel = screen
    .getByRole("heading", { name: m.ask_landing_heading() })
    .closest("section");
  expect(panel).not.toBeNull();
  expect(panel).toHaveClass("bg-cog-brand");
  expect(panel).toHaveClass("relative");
  expect(panel).toHaveClass("overflow-hidden");
  expect(panel).toHaveClass("rounded-2xl");
});

test("landing heading is the display-2xl white treatment", () => {
  renderLanding();
  const heading = screen.getByRole("heading", {
    name: m.ask_landing_heading(),
  });
  expect(heading).toHaveClass("text-display-2xl");
  expect(heading).toHaveClass("text-white");
});

test("landing body copy is white at 86% on the gradient", () => {
  renderLanding();
  const body = screen.getByText(m.ask_landing_body());
  expect(body).toHaveClass("text-white/86");
});

test("landing badge is the on-gradient frosted treatment", () => {
  renderLanding();
  const badge = screen.getByText(m.ask_landing_badge());
  expect(badge).toHaveClass("text-white");
  expect(badge).not.toHaveClass("bg-cog-surface-muted");
  expect(badge).not.toHaveClass("text-cog-text-eyebrow");
  // Frosted fill OR outline — either satisfies the on-gradient badge spec.
  const frosted =
    badge.classList.contains("bg-white/15") ||
    badge.classList.contains("border-white/40");
  expect(frosted).toBe(true);
});


