/**
 * Cross-locale copy invariants for the completion message (story #1284).
 *
 * The component tests can only ever pin the ACTIVE locale (en-US under vitest),
 * so an invariant that must hold in all 11 needs a test that actually looks at
 * all 11 — otherwise it is a documented intention with no enforcement, which is
 * precisely the kind of thing that drifts one translation at a time.
 *
 * Loads the locale files through `import.meta.glob` rather than `node:fs`:
 * ask-mfe's tsconfig declares only `vite/client` + `vitest/globals` types (no
 * `@types/node`), so `readFileSync`/`__dirname` do not typecheck here. This also
 * keeps the test inside ask-mfe — which IS in `frontend-test.yml`'s matrix —
 * rather than in platform-chrome, whose suite no CI job runs.
 *
 * Lives under `tests/` rather than `src/`: it asserts on message DATA, not on a
 * module, and `tests/` is excluded from the coverage floor.
 */

import { describe, expect, it } from "vitest";

/** Every locale's ask namespace, keyed by the glob's file path. */
const modules = import.meta.glob<{ readonly default: Record<string, unknown> }>(
  "../../messages/*/ask.json",
  { eager: true },
);

/** "…/messages/<locale>/ask.json" -> "<locale>". */
function localeOf(path: string): string {
  const parts = path.split("/");
  return parts[parts.length - 2] ?? "";
}

const BY_LOCALE: ReadonlyMap<string, Record<string, unknown>> = new Map(
  Object.entries(modules).map(([path, mod]) => [localeOf(path), mod.default]),
);

const LOCALES = [...BY_LOCALE.keys()].sort();

function messages(locale: string): Record<string, unknown> {
  const msgs = BY_LOCALE.get(locale);
  if (msgs === undefined) throw new Error(`no ask.json loaded for ${locale}`);
  return msgs;
}

/**
 * Reads a key that MUST be a present, non-empty string.
 *
 * Not `String(msgs[key])`: that coerces a missing key to the literal `"undefined"`,
 * which is a non-empty string and sails through every emptiness assertion below.
 * A locale that only half-landed this story would then pass the very guard meant
 * to catch it — and the one check that did fail (the character counter's tokens)
 * would blame missing interpolation rather than the missing key.
 */
function requireString(
  msgs: Record<string, unknown>,
  key: string,
  locale: string,
): string {
  const value = msgs[key];
  expect(typeof value, `${locale} / ${key} must be a string, got ${typeof value}`).toBe(
    "string",
  );
  return value as string;
}

describe("completion-message copy across every locale", () => {
  it("ships all 11 locales", () => {
    // Guards the guard: a glob that stopped matching would make every
    // assertion below vacuously pass over an empty list.
    expect(LOCALES).toHaveLength(11);
    expect(LOCALES).toContain("en-US");
    expect(LOCALES).toContain("ar-AE");
  });

  it.each(LOCALES)(
    "[%s] the field placeholder is byte-identical to the preview's default",
    (locale) => {
      // The Completion message field's placeholder IS the copy respondents see
      // when the author leaves it empty — that is how the field documents its
      // own fallback. If the two drift in some locale, the placeholder starts
      // promising text the preview will never render, and only speakers of that
      // locale would ever notice.
      const msgs = messages(locale);
      // Both must EXIST as strings before comparing: `undefined === undefined`
      // would make two absent keys look like perfect agreement.
      const placeholder = requireString(
        msgs,
        "ask_survey_editor_details_completion_placeholder",
        locale,
      );
      const fallback = requireString(msgs, "ask_survey_preview_completion_default", locale);
      expect(placeholder).toBe(fallback);
    },
  );

  it.each(LOCALES)("[%s] neither completion string is empty", (locale) => {
    const msgs = messages(locale);
    expect(requireString(msgs, "ask_survey_preview_completion_default", locale).trim()).not.toBe("");
    expect(
      requireString(msgs, "ask_survey_editor_details_completion_placeholder", locale).trim(),
    ).not.toBe("");
  });

  it.each(LOCALES)(
    "[%s] the character counter interpolates both {used} and {max}",
    (locale) => {
      // A counter that dropped a placeholder would render "of 500 characters"
      // or "12 of characters" — legible enough to survive review, useless to a
      // respondent counting their remaining room.
      const value = requireString(
        messages(locale),
        "ask_survey_editor_details_char_count",
        locale,
      );
      expect(value).toContain("{used}");
      expect(value).toContain("{max}");
    },
  );

  it.each(LOCALES)(
    "[%s] every preview string this story added is present and non-empty",
    (locale) => {
      // Keyset parity is the repo-wide i18n audit's job; this narrows it to THIS
      // story's keys so a half-landed follow-up fails here, in the owning
      // package, rather than only in the shared gate.
      const msgs = messages(locale);
      const previewKeys = Object.keys(msgs).filter((k) =>
        k.startsWith("ask_survey_preview_"),
      );
      expect(previewKeys.length).toBeGreaterThan(0);
      for (const key of previewKeys) {
        expect(requireString(msgs, key, locale).trim(), `${locale} / ${key}`).not.toBe("");
      }
      expect(
        requireString(msgs, "ask_survey_editor_details_discard_body", locale).trim(),
      ).not.toBe("");
    },
  );
});


