/**
 * Shared test factories (code review of story #2302).
 *
 * Lives under `tests/` rather than beside a suite because `vite.config.ts`
 * excludes `tests/**` from coverage — a factory is scaffolding, and counting it
 * would let fixture code prop up a per-file score.
 *
 * Deliberately small. Only builders that were about to exist in more than one
 * suite belong here; a fixture used by exactly one file is clearer next to the
 * test that reads it.
 */

import type { BranchDTO, BranchTarget } from "../src/api/branches";

/**
 * One conditional route: "answer `optionValue` on `questionId` → go to
 * `target`".
 *
 * The `id` is derived from the pair rather than random so a failure message
 * names the branch it came from. It has no meaning to any code under test —
 * branches are addressed by `(questionId, optionValue)`, which is the real key
 * both server-side and in `buildTraversalMap`.
 */
export function branchTo(
  questionId: string,
  optionValue: string,
  target: BranchTarget,
): BranchDTO {
  return { id: `b-${questionId}-${optionValue}`, questionId, optionValue, target };
}


