import "@testing-library/jest-dom/vitest";
import "vitest-axe/extend-expect";
import { setupServer } from "msw/node";
import {
  handlers,
  resetQuestionsFixture,
  resetSectionsFixture,
  resetSurveyPatches,
  resetSurveysFixture,
} from "./msw/handlers";
import { afterAll, afterEach, beforeAll, beforeEach, vi } from "vitest";
import { installResizeObserverStub } from "@omnicore-platform/ui/test-setup";

// jsdom does not implement ResizeObserver, but Radix primitives (Checkbox's
// useSize, Dialog/ToggleGroup) observe element size on mount — story #1278
// is ask-mfe's first use of the shared Checkbox/Dialog/ToggleGroup
// primitives together. Install the shared stub (see
// @omnicore-platform/ui/test-setup's own doc comment) rather than
// copy-pasting a local one.
installResizeObserverStub();

// jsdom does not implement window.matchMedia. Stub it globally so any
// component that calls matchMedia (e.g. ThemeProvider) doesn't crash in tests.
Object.defineProperty(window, "matchMedia", {
  writable: true,
  value: (query: string) => ({
    matches: false,
    media: query,
    onchange: null,
    addEventListener: () => undefined,
    removeEventListener: () => undefined,
    dispatchEvent: () => false,
  }),
});

/**
 * A FRESH in-memory localStorage before every test.
 *
 * Two problems this fixes at once.
 *
 * First, isolation. `useEditorCollapse` and `useSurveyViewMode` persist real
 * state, so one test collapsing an editor left the next test's editor already
 * collapsed — its "Collapse question 1" control was labelled "Expand question
 * 1" and every query for it failed. Tests in a file share one survey id, so
 * this was ordinary cross-test bleed, not an exotic race.
 *
 * Second, and worse, it was INVISIBLE locally. Node 26 does not expose a
 * usable localStorage to this runtime (it warns "localStorage is not available
 * because --localstorage-file was not provided"), so `safeStorage` swallowed
 * every write and nothing persisted — the suite passed. CI runs Node 20, where
 * localStorage works, so the pollution was real there and only there. Owning
 * storage here rather than inheriting whatever the runtime provides makes the
 * two environments agree.
 *
 * Individual files may still stub their own (AskLayout, useSurveyViewMode,
 * safeStorage, useEditorCollapse do, to drive specific failure modes); those
 * override this and are unaffected.
 */
function createMemoryStorage(): Storage {
  const map = new Map<string, string>();
  return {
    get length(): number {
      return map.size;
    },
    clear: () => map.clear(),
    getItem: (key: string) => map.get(key) ?? null,
    key: (index: number) => Array.from(map.keys())[index] ?? null,
    removeItem: (key: string) => void map.delete(key),
    setItem: (key: string, value: string) => void map.set(key, String(value)),
  };
}

beforeEach(() => {
  vi.stubGlobal("localStorage", createMemoryStorage());
});

// jsdom does not implement Element.prototype.scrollIntoView. Stub it as a
// no-op so components that call it don't crash.
if (!Element.prototype.scrollIntoView) {
  Element.prototype.scrollIntoView = function () {};
}

// MSW node server — intercepts fetch() calls in jsdom so component tests
// don't need to reach the real BFF.
export const server = setupServer(...handlers);

beforeAll(() => server.listen({ onUnhandledRequest: "warn" }));
afterEach(() => {
  server.resetHandlers();
  resetSurveysFixture();
  resetQuestionsFixture();
  resetSectionsFixture();
  resetSurveyPatches();
});
afterAll(() => server.close());


