// Tests for useSession — fetches /api/v1/session and unwraps the {data,error}
// envelope into a flat Session, with a module-level cache.
//
// fetchSession holds module-level `cached` / `inFlight` singletons, so each
// test re-imports the hook fresh (vi.resetModules) to isolate cache state.
// MSW (tests/setup.ts) backs the happy path; per-test server.use(...) drives
// the error branch. Mirrors frontends/spaces-mfe/tests/useSession.test.ts.

import { renderHook, waitFor } from "@testing-library/react";
import { http, HttpResponse } from "msw";
import { afterEach, beforeEach, expect, test, vi } from "vitest";
import { server } from "./setup";

beforeEach(() => {
  vi.resetModules();
});

afterEach(() => {
  server.resetHandlers();
});

async function loadHook() {
  // Fresh module → fresh `cached`/`inFlight` singletons per test.
  const mod = await import("../src/lib/useSession");
  return mod.useSession;
}

test("resolves to the ready state with the unwrapped session", async () => {
  const useSession = await loadHook();
  const { result } = renderHook(() => useSession());

  await waitFor(() => expect(result.current.state).toBe("ready"));
  if (result.current.state !== "ready") throw new Error("expected ready");
  expect(result.current.session.email).toBe("alice@example.com");
  expect(result.current.session.org_id).toBe("org-1");
});

test("surfaces the server-provided error message on a non-ok response", async () => {
  server.use(
    http.get("/api/v1/session", () =>
