/**
 * Regression guard — no bare in-ask navigation links.
 *
 * ask-mfe is mounted by shell-mfe at `/ask/*`. Any in-app navigation must
 * therefore carry the `/ask` prefix: a `to="/surveys/…"` or
 * `navigate("/surveys/…")` literal that omits `/ask` resolves at the shell
 * root and bounces the user out of Ask (the range-mfe `/range`-prefix lesson).
 *
 * This is a SOURCE-SCAN test. It reads every src file at compile time via
 * Vite's `import.meta.glob({ query: '?raw', eager: true })` — NOT node:fs —
 * because ask-mfe has no @types/node, so importing the node builtins would
 * break `tsc -b` (a CI gate). `import.meta.glob` is typed by `vite/client`
 * and runs in the jsdom/vitest worker.
 *
 * Route `path=` props stay UNPREFIXED (the parent /ask/* match supplies the
 * prefix); only `to=` / `navigate(` call sites are in-app navigation. The
 * guard fires on a navigation literal whose path begins with `/ask` but is
 * actually a bare survey path — for the scaffolding we only have the landing
 * route, so the guard's job is to stay green as routes are added in #1274.
 *
 * The regex matches a `to=`/`navigate(` target that is an ABSOLUTE path NOT
 * beginning with `/ask` (and not an `/api/` fetch URL, which never appears
 * in `to=`/`navigate(`). Correctly-prefixed links read `to="/ask/…"`.
 * `/profile` and `/account` are shell-mfe routes legitimately navigated from
 * the Topbar callbacks — allow them explicitly.
 */
import { describe, expect, it } from "vitest";

const SOURCE_FILES = import.meta.glob("/src/**/*.{ts,tsx}", {
  query: "?raw",
  import: "default",
  eager: true,
}) as Record<string, string>;

// Matches a navigation call site whose target is an absolute path that does
// NOT start with `/ask` (e.g. to="/surveys", navigate("/responses/…")).
// `to="/ask/…"` has `ask` directly after the leading slash, so it never
// matches — that IS the required shape for in-app links. `/profile` and
// `/account` are shell-mfe routes legitimately navigated from the Topbar
// callbacks, so allow them explicitly.
const BARE_NAV_LINK =
  /(?:to=|navigate\()\s*\{?\s*[`'"]\/(?!ask[/`'"]|profile|account)[a-z]/;

describe("ask-mfe in-app navigation links", () => {
  it("never navigates to a bare path missing the /ask prefix", () => {
    const offenders: string[] = [];

    for (const [path, source] of Object.entries(SOURCE_FILES)) {
      source.split("\n").forEach((line, i) => {
        if (BARE_NAV_LINK.test(line)) {
          offenders.push(`${path}:${i + 1}: ${line.trim()}`);
        }
      });
    }

    expect(
      offenders,
      `Found in-ask navigation links missing the /ask prefix:\n${offenders.join(
        "\n",
      )}`,
    ).toEqual([]);
  });

  it("scans a non-empty set of source files (guards against a broken glob)", () => {
    expect(Object.keys(SOURCE_FILES).length).toBeGreaterThan(0);
  });
});


